#!/usr/bin/env python3
"""Disposable local task fixture (mechanism smoke only; not autonomous S1 evidence)."""
import hashlib
from datetime import date
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse
from html import escape
PORT = 18791
class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        dest = q.get("destination",[""])[0]
        start = q.get("startDate",[""])[0]
        end = q.get("endDate",[""])[0]
        valid = False
        try:
            valid = bool(dest.strip()) and date.fromisoformat(start) < date.fromisoformat(end)
        except ValueError:
            pass
        if u.path == "/Hotel-Search" and valid:
            normalized = dest.lower().strip()+"|"+start+"|"+end
            token=hashlib.sha256(normalized.encode()).hexdigest()[:12]
            body=f"""<!doctype html><title>Search Results</title><h1 id="search-result">VERIFIED</h1><div id="result-id">{token}</div><div id="dates">{escape(start)} — {escape(end)}</div><div id="destination">{escape(dest)}</div>"""
        else:
            body="""<!doctype html><title>Task Fixture</title><h1>Date-constrained search</h1>
            <p>Complete a hotel search for a destination and two dates.</p>
            <form id="search"><input id="destination" placeholder="destination"/>
            <input id="start" type="date"/><input id="end" type="date"/>
            <button id="submit" type="submit">Search</button></form>
            <div id="feedback"></div>
            <script>
            // Synthetic failure: each date selection is dropped by the widget during submission.
            document.querySelector('#search').addEventListener('submit', e=>{
              e.preventDefault();
              document.querySelector('#start').value = '';
              document.querySelector('#end').value = '';
              document.querySelector('#feedback').textContent = 'Dates were not retained; search not submitted';
            });
            </script>"""
        encoded=body.encode()
        self.send_response(200);self.send_header("Content-Type","text/html; charset=utf-8");self.send_header("Content-Length",str(len(encoded)));self.end_headers()
        self.wfile.write(encoded)
    def log_message(self,*args): pass
if __name__=="__main__":
    ThreadingHTTPServer(("127.0.0.1",PORT),Handler).serve_forever()
